local ProcessionalCrossMaker = {}
local PRODUCTS = {
    wooden_cross = { name = "Leseni procesijski križ", woodCost = 2, time = 2, cost = 25, sanctity = 4, description = "Preprost lesen procesijski križ." },
    brass_cross = { name = "Medeninast križ", brassCost = 2, woodCost = 1, time = 4, cost = 95, sanctity = 8, prestige = 2, description = "Medeninast procesijski križ za župnije." },
    silver_cross = { name = "Srebrni križ", silverCost = 2, woodCost = 1, time = 6, cost = 240, sanctity = 12, prestige = 6, happiness = 1, description = "Srebrni procesijski križ za slovesnosti." },
    gold_cross = { name = "Zlati križ", goldCost = 1, silverCost = 1, woodCost = 1, time = 8, cost = 540, sanctity = 16, prestige = 12, happiness = 2, description = "Zlati procesijski križ za škofe." },
    jewel_cross = { name = "Draguljni križ", goldCost = 2, silverCost = 1, jewelCost = 2, time = 11, cost = 1200, sanctity = 22, prestige = 22, happiness = 5, description = "Procesijski križ z dragulji za katedralo." },
    royal_cathedral_cross = { name = "Kraljevski katedralni križ", goldCost = 4, silverCost = 2, jewelCost = 4, pearlCost = 2, time = 16, cost = 2900, sanctity = 38, prestige = 65, happiness = 13, description = "Veliki kraljevski katedralni procesijski križ z dragulji in biseri." },
}
local BUILDINGS = {
    workshop = { name = "Križarska delavnica", cost = { gold = 290, wood = 130 }, upkeep = 7, qualityBonus = 5 },
    forge = { name = "Križarska kovačija", cost = { gold = 900, wood = 220, stone = 200, silver = 6 }, upkeep = 22, qualityBonus = 18 },
    jewel_room = { name = "Draguljna soba", cost = { gold = 1900, wood = 300, stone = 400, silver = 25, jewel = 8 }, upkeep = 45, qualityBonus = 30 },
    royal_cross_atelier = { name = "Kraljevski atelje križev", cost = { gold = 7500, wood = 600, stone = 800, gold = 80, jewel = 25 }, upkeep = 140, qualityBonus = 55, prestigeBonus = 35 },
}
ProcessionalCrossMaker.woodStock = 14; ProcessionalCrossMaker.brassStock = 8; ProcessionalCrossMaker.silverStock = 8; ProcessionalCrossMaker.goldStock = 6; ProcessionalCrossMaker.jewelStock = 6; ProcessionalCrossMaker.pearlStock = 4
ProcessionalCrossMaker.productStock = {}; ProcessionalCrossMaker.buildings = {}; ProcessionalCrossMaker.maker = nil; ProcessionalCrossMaker.activeMaking = {}; ProcessionalCrossMaker.totalProducts = 0; ProcessionalCrossMaker.dayTimer = 0
function ProcessionalCrossMaker.init() ProcessionalCrossMaker.woodStock=14; ProcessionalCrossMaker.brassStock=8; ProcessionalCrossMaker.silverStock=8; ProcessionalCrossMaker.goldStock=6; ProcessionalCrossMaker.jewelStock=6; ProcessionalCrossMaker.pearlStock=4; ProcessionalCrossMaker.productStock={}; ProcessionalCrossMaker.buildings={}; ProcessionalCrossMaker.maker=nil; ProcessionalCrossMaker.activeMaking={}; ProcessionalCrossMaker.totalProducts=0; ProcessionalCrossMaker.dayTimer=0; print("[ProcessionalCrossMaker] Royal Processional Cross Maker System initialized (6 products, 4 buildings)") end
function ProcessionalCrossMaker.hireMaker(n,s) s=s or math.random(50,90); local c=490+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ProcessionalCrossMaker.maker={name=n or ("Križar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Križar najet: %s (spretnost: %d)",ProcessionalCrossMaker.maker.name,s),"success") end; return true end
function ProcessionalCrossMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ProcessionalCrossMaker.build(id) local ok,e=ProcessionalCrossMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ProcessionalCrossMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ProcessionalCrossMaker.getQualityBonus() local b=0; for _,bd in ipairs(ProcessionalCrossMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ProcessionalCrossMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ProcessionalCrossMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.brassCost and ProcessionalCrossMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and ProcessionalCrossMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ProcessionalCrossMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ProcessionalCrossMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ProcessionalCrossMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ProcessionalCrossMaker.buildings==0 then return false,"Potrebna delavnica" end; if not ProcessionalCrossMaker.maker then return false,"Potreben križar" end; return true end
function ProcessionalCrossMaker.make(pt,qty) qty=qty or 1; local ok,e=ProcessionalCrossMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ProcessionalCrossMaker.woodStock=ProcessionalCrossMaker.woodStock-d.woodCost*qty end; if d.brassCost then ProcessionalCrossMaker.brassStock=ProcessionalCrossMaker.brassStock-d.brassCost*qty end; if d.silverCost then ProcessionalCrossMaker.silverStock=ProcessionalCrossMaker.silverStock-d.silverCost*qty end; if d.goldCost then ProcessionalCrossMaker.goldStock=ProcessionalCrossMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ProcessionalCrossMaker.jewelStock=ProcessionalCrossMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ProcessionalCrossMaker.pearlStock=ProcessionalCrossMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ProcessionalCrossMaker.maker then t=math.max(1,t-math.floor(ProcessionalCrossMaker.maker.skill/12)) end; table.insert(ProcessionalCrossMaker.activeMaking,{id="cross_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,sanctity=d.sanctity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ProcessionalCrossMaker.completeMaking(m) local q=1.0+(ProcessionalCrossMaker.getQualityBonus()/100); if ProcessionalCrossMaker.maker then q=q+(ProcessionalCrossMaker.maker.skill/180) end; q=math.min(2.0,q); ProcessionalCrossMaker.productStock[m.productType]=(ProcessionalCrossMaker.productStock[m.productType] or 0)+m.quantity; ProcessionalCrossMaker.totalProducts=ProcessionalCrossMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ProcessionalCrossMaker.maker then ProcessionalCrossMaker.maker.itemsMade=ProcessionalCrossMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then ProcessionalCrossMaker.maker.skill=math.min(100,ProcessionalCrossMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Križ izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"processionalcross.completed",{productName=m.productName,sanctity=m.sanctity}) end end
function ProcessionalCrossMaker.update(dt) if not _G.state then return end; ProcessionalCrossMaker.dayTimer=ProcessionalCrossMaker.dayTimer+dt; if ProcessionalCrossMaker.dayTimer>=30 then ProcessionalCrossMaker.dayTimer=0; for i=#ProcessionalCrossMaker.activeMaking,1,-1 do local m=ProcessionalCrossMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ProcessionalCrossMaker.completeMaking(m); table.remove(ProcessionalCrossMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ProcessionalCrossMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ProcessionalCrossMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ProcessionalCrossMaker.getStats() return {woodStock=ProcessionalCrossMaker.woodStock,brassStock=ProcessionalCrossMaker.brassStock,silverStock=ProcessionalCrossMaker.silverStock,goldStock=ProcessionalCrossMaker.goldStock,jewelStock=ProcessionalCrossMaker.jewelStock,pearlStock=ProcessionalCrossMaker.pearlStock,productStock=ProcessionalCrossMaker.productStock,numBuildings=#ProcessionalCrossMaker.buildings,hasMaker=ProcessionalCrossMaker.maker~=nil,makerName=ProcessionalCrossMaker.maker and ProcessionalCrossMaker.maker.name or "—",makerSkill=ProcessionalCrossMaker.maker and ProcessionalCrossMaker.maker.skill or 0,activeMaking=#ProcessionalCrossMaker.activeMaking,totalProducts=ProcessionalCrossMaker.totalProducts} end
return ProcessionalCrossMaker
